import java.io.*;

public class Perturbed2 {
    static boolean DEBUG_FLAG = false;

    static long solve(long n, long m) {
        if (n > m) {
            n = n + m;
            m = n - m;
            n = n - m;
        }
        long area = n * m;
        if (n <= 3 && m <= 3) {
            if (n == 1 || m == 1) return 0;
            if (n == 2 && m == 3) return 4;
            if (n == 3 && m == 3) return 8;
            return 0;
        }
        if (n == 1) {
            long rem = m % 6;
            if (rem == 4) rem = 2;
            else if (rem == 5) rem = 1;
            return area - rem;
        }
        if (n == 2) {
            if (m == 3 || m == 7) return area - 2;
            return area;
        }
        return area - area % 2;
    }

    private static int readInt(BufferedReader in) throws IOException {
        int c;
        do {
            c = in.read();
        } while (c != -1 && Character.isWhitespace(c));
        if (c == -1) throw new IOException("EOF");
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = in.read();
        }
        int val = 0;
        while (c != -1 && !Character.isWhitespace(c)) {
            val = val * 10 + (c - '0');
            c = in.read();
        }
        return val * sign;
    }

    public static void main(String[] args) throws IOException {
        if (args.length > 0 && args[0].equalsIgnoreCase("d")) DEBUG_FLAG = true;
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        long start = System.nanoTime();
        int n = readInt(br);
        int m = readInt(br);
        out.println(solve(n, m));
        long end = System.nanoTime();

        debug("\nTime: " + (end - start) / 1e6 + " \n\n");
        out.close();
    }

    static void debug(String s) {
        if (DEBUG_FLAG) System.out.print(s);
    }
}
